<?php get_header(); $product = oubei_get_product_data(get_the_ID()); ?>
<main class="oubei-section"><div class="oubei-container oubei-product-detail"><p class="eyebrow"><?php echo esc_html($product['code'] ?? ''); ?></p><h1><?php echo esc_html($product['name'] ?? get_the_title()); ?></h1><div class="oubei-product-detail__grid"><div class="oubei-product-detail__image"><?php $image_id = (int) ($product['featured_image_id'] ?? 0); if ($image_id) { echo wp_kses_post(wp_get_attachment_image($image_id, 'large')); } else { $slot = oubei_get_media_slot('products.' . ($product['slug'] ?? '')); ?><img src="<?php echo esc_url($slot['url']); ?>" alt="<?php echo esc_attr($slot['alt']); ?>"><?php } ?></div><div><p class="lede lede--dark"><?php echo esc_html($product['short_description'] ?: wp_strip_all_tags($product['description'])); ?></p><dl class="oubei-product-meta"><div><dt>Material</dt><dd><?php echo esc_html($product['material']); ?></dd></div><div><dt>Category</dt><dd><?php echo esc_html(implode(', ', array_column($product['categories'], 'name'))); ?></dd></div></dl><?php if ($product['applications']) : ?><h2>Applications</h2><ul><?php foreach ($product['applications'] as $item) : ?><li><?php echo esc_html($item); ?></li><?php endforeach; ?></ul><?php endif; ?><?php if ($product['specs']) : ?><h2>Specifications</h2><ul><?php foreach ($product['specs'] as $item) : ?><li><?php echo esc_html($item); ?></li><?php endforeach; ?></ul><?php endif; ?><a class="button button--accent" href="<?php echo esc_url(home_url('/quote')); ?>">Request a quote</a></div></div></div></main><?php get_footer();
